// Generated by OrchestKit Claude Plugin
// Created: 2026-08-25

/**
 * Empty Result Detector - SubagentStop Hook (#3739)
 *
 * A subagent can finish with `status: completed` while delivering NO final
 * assistant text to its parent. The parent sees a completion notification with
 * an empty or preamble-only result, which reads as "the agent found nothing"
 * when it actually means "the delegation failed and its work is stranded".
 * Measured cost of that ambiguity: four agents in one session, two of which had
 * done real work, one having committed a fix locally that was never pushed.
 *
 * MEASURED BASE RATE, 2026-08-25, across 2,735 real subagent transcripts on
 * this machine:
 *
 *   delivered a report (final text > 200 chars)   2,380   87.0%
 *   short final text                                258    9.4%
 *   NO final assistant text at all                   97    3.5%   <- this hook
 *
 * The last event on those 97 is a `tool_result` 68 times, a denied tool 13
 * times, a `tool_use` 11 times and a `thinking` block 5 times. So the dominant
 * shape is an agent stopping immediately after a tool returns, without ever
 * emitting a closing message. Denials are a real but minority trigger, which
 * refuted the first hypothesis that this was purely a guard-denial artefact.
 *
 * WHAT THIS HOOK DOES NOT DO: it does not return `continue: false` to force the
 * agent to speak. CC 2.1.78 fixed an infinite loop caused by stop hooks
 * re-feeding the model, and `sync-subagent-stop-dispatcher` short-circuits on a
 * blocking result, which would starve every hook queued behind it (the #3200
 * starvation class). Making the failure LOUD is the whole job here; recovering
 * the lost text is not possible from this position, because the agent's turn is
 * already over.
 *
 * @behavior warns via systemMessage; never blocks
 */

import { existsSync, statSync, openSync, readSync, closeSync } from 'node:fs';
import type { HookInput, HookResult, HookContext } from '../types.js';
import { outputSilentSuccess, logHook } from '../lib/common.js';
import { NOOP_CTX } from '../lib/context.js';

const HOOK_NAME = 'empty-result-detector';

/** Only read the tail of a transcript: they reach megabytes and this is a stop-path hook. */
const TAIL_BYTES = 256 * 1024;

/**
 * The three outcomes must stay distinct. Conflating UNOBSERVABLE with EMPTY is
 * what turned output-validator into a kill-switch (#3200): it reported an
 * absent payload field as a validation error on every single row.
 */
export type ResultVerdict = 'delivered' | 'empty' | 'unobservable';

export interface TranscriptTail {
  verdict: ResultVerdict;
  /** Kind of the final content block, when one could be read. */
  lastBlock?: string;
  /** Length of the final assistant text, 0 when none was emitted. */
  finalTextLength: number;
  /** Reason the transcript could not be inspected, when unobservable. */
  reason?: string;
}

/** Read the last TAIL_BYTES of a file without loading the whole thing. */
function readTail(path: string): string | null {
  let fd: number | undefined;
  try {
    const size = statSync(path).size;
    const start = Math.max(0, size - TAIL_BYTES);
    const length = size - start;
    if (length <= 0) return '';
    const buf = Buffer.alloc(length);
    fd = openSync(path, 'r');
    readSync(fd, buf, 0, length, start);
    return buf.toString('utf8');
  } catch {
    return null;
  } finally {
    if (fd !== undefined) {
      try { closeSync(fd); } catch { /* silent: post-cleanup */ }
    }
  }
}

/**
 * Decide whether the agent delivered a closing message.
 *
 * Exported for testing, and because the classification is the load-bearing part
 * of this hook: everything else is plumbing.
 */
export function classifyTranscript(transcriptPath: string | undefined): TranscriptTail {
  if (!transcriptPath) {
    return { verdict: 'unobservable', finalTextLength: 0, reason: 'no agent_transcript_path in payload' };
  }
  if (!existsSync(transcriptPath)) {
    return { verdict: 'unobservable', finalTextLength: 0, reason: 'transcript path not on disk' };
  }
  const tail = readTail(transcriptPath);
  if (tail === null) {
    return { verdict: 'unobservable', finalTextLength: 0, reason: 'transcript unreadable' };
  }

  // Walk forward through the tail and remember the LAST content block seen. A
  // truncated first line is expected when the tail starts mid-file, so parse
  // failures are skipped rather than treated as evidence.
  let lastBlock: string | undefined;
  let finalTextLength = 0;
  let sawAnyBlock = false;

  for (const line of tail.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    let row: unknown;
    try {
      row = JSON.parse(trimmed);
    } catch {
      continue;
    }
    const message = (row as { message?: { content?: unknown } }).message;
    const content = message?.content;
    if (!Array.isArray(content)) continue;
    for (const block of content) {
      const b = block as { type?: string; text?: string };
      if (!b || typeof b.type !== 'string') continue;
      if (b.type === 'text') {
        const text = (b.text ?? '').trim();
        // An empty text block is not a delivered message.
        if (!text) continue;
        lastBlock = 'text';
        finalTextLength = text.length;
      } else {
        lastBlock = b.type;
        finalTextLength = 0;
      }
      sawAnyBlock = true;
    }
  }

  if (!sawAnyBlock) {
    return { verdict: 'unobservable', finalTextLength: 0, reason: 'no content blocks in transcript tail' };
  }
  return {
    verdict: lastBlock === 'text' ? 'delivered' : 'empty',
    lastBlock,
    finalTextLength,
  };
}

/** The marker the parent sees instead of nothing. */
export function buildMarker(agent: string, tail: TranscriptTail): string {
  const last = tail.lastBlock ?? 'unknown';
  return [
    `EMPTY RESULT: subagent '${agent}' completed WITHOUT delivering a final message.`,
    `Its transcript ends on a '${last}' block, not on assistant text.`,
    '',
    'This is a FAILED delegation, not an empty finding. Do not read the silence',
    'as "nothing to report" and do not write the report the agent did not deliver.',
    '',
    'Recover deliberately: check the agent transcript for work it completed but',
    'never reported (commits, edits, files written), and re-derive the answer',
    'yourself rather than re-prompting for a summary the agent no longer has.',
  ].join('\n');
}

export function emptyResultDetector(input: HookInput, ctx: HookContext = NOOP_CTX): HookResult {
  const agent = input.subagent_type || input.agent_type || 'unknown';
  const tail = classifyTranscript(input.agent_transcript_path);

  if (tail.verdict === 'unobservable') {
    // Say nothing. A transcript we could not read is not evidence that the
    // agent was silent, and a false "empty result" warning on every row would
    // train the reader to ignore the real ones.
    ctx.log(HOOK_NAME, `unobservable for ${agent}: ${tail.reason}`, 'debug');
    return outputSilentSuccess();
  }

  if (tail.verdict === 'delivered') {
    ctx.log(HOOK_NAME, `${agent} delivered ${tail.finalTextLength} chars`, 'debug');
    return outputSilentSuccess();
  }

  ctx.log(HOOK_NAME, `EMPTY RESULT: ${agent} ended on '${tail.lastBlock}' with no final text`);
  logHook(HOOK_NAME, `empty result: agent=${agent} lastBlock=${tail.lastBlock}`);

  return {
    continue: true,
    systemMessage: buildMarker(agent, tail),
  };
}
